UPDATE RESERVATIONS
SET user_id         = #{userId},
    reserved_status = 'RESERVED',
    reserved_at     = NOW(),
    upt_id          = #{uptId},
    upt_ip          = #{uptIp}
WHERE reservation_id = #{reservationId}
  AND round_id = #{roundId}
  AND seat_id  = #{seatId}
  AND user_id IS NULL

mapper.select:
SELECT h.history_id AS historyId, h.user_id AS userId, h.seat_id AS seatId, h.round_id AS roundId, h.action AS reservedStatus, h.created_at AS createdReserved, h.ins_ip AS insIp, s.seat_row AS seatRow, s.seat_colume AS seatColume, s.grade, p.p_title AS pTitle, pr.round_time AS roundTime FROM RESERVATION_HISTORY h JOIN SEATS s ON h.seat_id = s.seat_id JOIN PERFORMANCE_ROUND pr ON h.round_id = pr.round_id JOIN PERFORMANCES p ON pr.performance_id = p.performance_id WHERE h.created_at >= #{from} AND h.created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)
AND h.user_id = #{userId}
AND h.action = #{action}
ORDER BY h.created_at DESC

SELECT COUNT(*)
FROM RESERVATIONS
WHERE user_id = #{userId}
  AND round_id = #{roundId}
  AND reserved_status = 'RESERVED'
